(function(root){'use strict';
root.MT_WORKSPACE_APP.register({notebook:async c=>{const chapter=(globalThis.MT_PARSE_NUMBER||Number)(c.params.get('chapter')||1);if(!Number.isInteger(chapter)||chapter<1||chapter>16)throw Error('Choose a valid chapter.');const data=c.store.data,editing=data.notes.find(n=>n.id===c.params.get('note')),sourceCases=data.cases.filter(v=>v.snapshot.charts?.length),notes=data.notes.filter(n=>n.chapter===chapter);
return {html:'<h1>Your workbook</h1><p class="next-intro">Keep explanations and annotated experiments with their chapter.</p><section class="panel"><label>Chapter<select id="notebook-chapter">'+c.chapterOptions(chapter)+'</select></label><form id="notebook-form"><label>Your note<textarea id="notebook-body" maxlength="20000">'+c.esc(editing?.body||'')+'</textarea></label><label>Optional saved experiment<select id="notebook-case"><option value="">Text note</option>'+c.options(sourceCases.map(v=>[v.id,v.title]),editing?.caseId)+'</select></label><div id="notebook-image"></div><fieldset><legend>Diagram annotations</legend><p>Choose a point in the diagram, or enter its horizontal and vertical percentage. Position controls also work with the keyboard.</p><div class="fields"><label>Horizontal position · %<input id="annotation-x" type="number" min="0" max="100" step=".1" value="50"></label><label>Vertical position · %<input id="annotation-y" type="number" min="0" max="100" step=".1" value="50"></label></div><label>Annotation text<input id="annotation-text" maxlength="300"></label><button id="annotation-add" type="button">Add annotation</button><div id="annotation-list"></div></fieldset><button type="submit">'+(editing?'Save revision':'Save workbook note')+'</button></form></section><section class="panel"><h2>Chapter notes</h2><div class="next-actions"><button id="notebook-export"'+(!notes.length?' disabled':'')+'>Export chapter workbook</button></div>'+(notes.length?notes.map(n=>'<article class="next-step"><p>'+c.esc(new Date(n.createdAt).toLocaleString())+'</p><div class="next-summary" data-user-content>'+c.esc(n.body)+'</div>'+(n.annotations?.length?'<ul>'+n.annotations.map(a=>'<li>'+c.user(a.text)+'</li>').join('')+'</ul>':'')+'<div class="next-actions"><a href="#notebook?chapter='+chapter+'&note='+encodeURIComponent(n.id)+'">Edit note</a><button data-delete-note="'+c.esc(n.id)+'">Delete note</button></div></article>').join(''):c.empty('No workbook notes for this chapter yet.'))+'</section>',bind(){let annotations=c.W.clean(editing?.annotations||[]);function draw(){const chosen=sourceCases.find(v=>v.id===c.$('notebook-case').value);c.$('notebook-image').innerHTML=chosen?'<h3 data-user-content>'+c.esc(chosen.title)+'</h3><div class="next-annotation" id="annotation-canvas">'+c.safeSvg(chosen.snapshot.charts[0].svg)+annotations.map(a=>'<span class="next-annotation-label" style="left:'+a.x*100+'%;top:'+a.y*100+'%">'+c.user(a.text)+'</span>').join('')+'</div>':'';c.$('annotation-list').innerHTML=annotations.length?'<ol>'+annotations.map((a,i)=>'<li>'+c.user(a.text)+' · '+Math.round(a.x*100)+'%, '+Math.round(a.y*100)+'% <button type="button" data-remove-annotation="'+i+'">Remove</button></li>').join('')+'</ol>':'<p>No diagram annotations.</p>';document.querySelectorAll('[data-remove-annotation]').forEach(b=>b.onclick=()=>{annotations.splice((globalThis.MT_PARSE_NUMBER||Number)(b.dataset.removeAnnotation),1);draw();});const canvas=c.$('annotation-canvas');if(canvas)canvas.onclick=e=>{const bounds=canvas.getBoundingClientRect();c.$('annotation-x').value=String(Math.max(0,Math.min(100,(e.clientX-bounds.left)/bounds.width*100)).toFixed(1));c.$('annotation-y').value=String(Math.max(0,Math.min(100,(e.clientY-bounds.top)/bounds.height*100)).toFixed(1));c.$('annotation-text').focus();};}
c.on('notebook-chapter','change',()=>location.hash='notebook?chapter='+c.$('notebook-chapter').value);c.on('notebook-case','change',()=>{annotations=[];draw();});c.button('annotation-add',()=>{if(!c.$('notebook-case').value)throw Error('Choose a saved experiment before annotating it.');const text=c.$('annotation-text').value.trim(),x=(globalThis.MT_PARSE_NUMBER||Number)(c.$('annotation-x').value)/100,y=(globalThis.MT_PARSE_NUMBER||Number)(c.$('annotation-y').value)/100;if(!text||!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>1||y<0||y>1||annotations.length>=50)throw Error('Enter annotation text and positions from 0 to 100%. Up to 50 annotations are supported.');annotations.push({text,x,y});c.$('annotation-text').value='';draw();});c.on('notebook-form','submit',e=>{e.preventDefault();const body=c.$('notebook-body').value;if(!body.trim()&&!annotations.length)throw Error('Write a note or add an annotation.');const caseId=c.$('notebook-case').value||null;if(editing)c.store.updateNote(editing.id,{chapter,body,caseId,annotations});else c.store.saveNote(chapter,body,caseId,annotations);location.hash='notebook?chapter='+chapter;c.refresh();c.message('Workbook note saved.');});document.querySelectorAll('[data-delete-note]').forEach(b=>b.onclick=()=>{if(confirm('Delete this workbook note?')){c.store.remove('notes',b.dataset.deleteNote);c.refresh();}});c.button('notebook-export',()=>{const html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marine Tools workbook · Chapter '+chapter+'</title><style>body{font:16px/1.6 Arial;max-width:1000px;margin:32px auto;padding:0 20px}article{margin:32px 0;break-inside:avoid}.image{position:relative}.image svg{width:100%;height:auto;margin:0}.annotation{position:absolute;background:#f8ce81;color:#071725;padding:3px 6px;transform:translate(-50%,-50%);font-size:13px;max-width:180px}p{white-space:pre-wrap}</style><h1>Workbook · Chapter '+chapter+'</h1>'+notes.map(n=>{const source=data.cases.find(v=>v.id===n.caseId),svg=source?.snapshot.charts?.[0]?.svg;return '<article><h2>'+c.esc(new Date(n.createdAt).toLocaleString())+'</h2><p>'+c.esc(n.body)+'</p>'+(svg?'<div class="image">'+c.safeSvg(svg)+(n.annotations||[]).map(a=>'<span class="annotation" style="left:'+a.x*100+'%;top:'+a.y*100+'%">'+c.user(a.text)+'</span>').join('')+'</div>':'')+'</article>';}).join('');c.download('MarineTools-workbook-chapter-'+chapter+'.html',html,'text/html;charset=utf-8');});draw();}};}});
})(window);
